"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 1 (P1 v0.4, section 5.2): new recording classes (footsteps, door, cupboard/drawer).

select:   FSD50K single-source clips (the only leaf label is the class), CC0 or CC BY 3.0/4.0, rated present and
          predominant, curated from title, tags and description by the fixed rules below, before any audio is used:
            - footsteps: indoor surfaces only, no other named sound source;
            - door: house or room doors (no vehicles, appliances, furniture, gates, sliding or metal doors, no knock,
              bell or footsteps), labelled opening, closing, both or unknown from the text. Because the strict pool is
              small, door also takes clips whose leaf labels are within {Door, Squeak, Slam} (plan 5.2, "relaxed");
            - cabinet: Cupboard_open_or_close and Drawer_open_or_close (household furniture; no real doors).
          Writes results/step0_v04/new_selection.json ({clip: class, kind, uploader, licence, split, text}).
check:    fingerprints (threshold of scripts/step0_fingerprint.py, 48 aligned matches): MUSAN noise matches are
          excluded; "same sound" links among the new clips and to the v0.3 pool clips; the false-match rate of the
          threshold between the new classes and unrelated v0.3 classes. Writes results/step0_v04/new_check.json.
allocate: uploader mapping. An uploader already in a v0.3 split (FSD50K pools or the Freesound subset) keeps that
          split, and so does a clip linked by fingerprint to a v0.3 clip. The remaining clips form groups (same uploader
          or same sound), split per class in proportion (test 30%, replication 15%, dev 10%, train 45%; seeded; as
          amendment A1 of v0.3). Reports clips, uploaders and groups per class and split (test minimum: 8 groups per
          class). Writes results/step0_v04/new_split.json.
usage: python -I scripts/step0v4_new_classes.py select|check|allocate
"""
import json
import os
import random
import re
import sys
from collections import Counter, defaultdict

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import step0_fsd50k_counts as C  # noqa: E402

ROOT = "data/fsd50k_dl/x"
OUT = "results/step0_v04"
CLIPS = "data/fsd50k_sel"
MUSAN = "data/musan_dl/musan/noise"
SEED = 20261115

INDOOR = re.compile(r"\b(indoors?|inside|interior|room|house|home|apartment|flat|hall|hallway|corridor|stairs?|"
                    r"staircase|stairway|upstairs|downstairs|floors?|floorboards?|wood|wooden|parquet|laminate|tiles?|"
                    r"tiled|carpet|carpeted|kitchen|bedroom|livingroom|office|linoleum|creaky)\b")
OUTDOOR = re.compile(r"\b(snow|snowy|gravel|grass|grassy|sand|sandy|mud|muddy|leaves|leaf|forest|woods|street|road|"
                     r"pavement|sidewalk|asphalt|outdoors?|outside|park|beach|dirt|puddles?|water|ice|icy|rain|path|"
                     r"trail|field|garden|cobbles?|cobblestones?|hike|hiking|crunch|crunchy|bridge|deck|dock|pier|"
                     r"stone|rocks?|metal|ladder|platform|station)\b")
STEP_CONTAM = re.compile(r"\b(door|doors|knock|knocking|bell|ring|ringing|phone|voices?|talk|talking|speech|speaking|"
                         r"music|dog|cat|birds?|car|cars|train|crowd|people|laugh|laughing|cough|tv|radio|horse|"
                         r"keys?|jingle)\b")
DOOR_EXCL = re.compile(r"\b(car|truck|van|vehicle|bus|train|subway|metro|tram|plane|airplane|aircraft|elevator|lift|"
                       r"fridge|refrigerator|freezer|oven|microwave|dishwasher|washer|dryer|cupboard|cabinet|wardrobe|"
                       r"closet|drawers?|locker|safe|vault|gate|garage|shed|barn|sliding|slide|automatic|shop|store|"
                       r"prison|jail|cell|dungeon|castle|church|metal|iron|steel|hatch|trapdoor|window|shutter|stall|"
                       r"box|case|chest|trunk|mailbox|letterbox|knock|knocking|knocks|bell|doorbell|ring|buzzer|"
                       r"intercom|phone|voices?|talk|talking|speech|music|dog|footsteps|steps|walking|walk|alarm|"
                       r"beep|horror|scary|monster|ghost|game|cartoon|synth|synthesized|processed|reverse|reversed)\b")
OPEN = re.compile(r"\b(open|opens|opening|opened|unlock|unlocks|unlocking|unlocked)\b")
CLOSE = re.compile(r"\b(close|closes|closing|closed|shut|shuts|shutting|slam|slams|slamming|slammed)\b")
CAB_EXCL = re.compile(r"\b(car|fridge|refrigerator|freezer|oven|microwave|dishwasher|knock|knocking|bell|doorbell|ring|"
                      r"phone|voices?|talk|talking|speech|music|dog|footsteps|walking|front|entrance|gate|garage|"
                      r"alarm|beep|horror|game|synth|processed|reverse|reversed)\b")


def text_of(i):
    tags = i["tags"] if isinstance(i["tags"], list) else [str(i["tags"])]
    return " ".join([i.get("title", ""), " ".join(tags), i.get("description", "")]).lower().replace("_", " ")


def select():
    gt, info, ratings = C.load(ROOT)
    anc = C.infer_ancestors(gt)
    name2mid = {l: m for c in gt.values() for l, m in zip(c["labels"], c["mids"])}

    def leaves(f):
        labs = set(gt[f]["labels"])
        return {l for l in labs if not any(l in anc.get(o, ()) for o in labs if o != l)}

    def pp(f, cls):
        r = ratings.get(f, {}).get(name2mid[cls])
        return bool(r) and 1.0 in r and min(r) >= 1.0

    out, reasons = {}, defaultdict(Counter)
    for f in gt:
        i = info[f]
        if not C.OK_LICENSE.search(i["license"]):
            continue
        lv, t = leaves(f), text_of(i)
        rec = {"uploader": i["uploader"], "license": i["license"], "fsd50k_split": gt[f]["split"],
               "title": i.get("title", ""), "labels": sorted(lv)}
        if lv == {"Walk_and_footsteps"} and pp(f, "Walk_and_footsteps"):
            if OUTDOOR.search(t):
                reasons["footsteps"]["outdoor word"] += 1
            elif STEP_CONTAM.search(t):
                reasons["footsteps"]["other source word"] += 1
            elif not INDOOR.search(t):
                reasons["footsteps"]["no indoor word"] += 1
            else:
                out[f] = {**rec, "class": "footsteps", "kind": "steps"}
        elif "Door" in gt[f]["labels"] and lv and lv <= {"Door", "Squeak", "Slam"} and pp(f, "Door"):
            if DOOR_EXCL.search(t):
                reasons["door"]["excluded word"] += 1
                continue
            o, c = bool(OPEN.search(t)), bool(CLOSE.search(t))
            kind = "both" if o and c else "open" if o else "close" if c else "unknown"
            out[f] = {**rec, "class": "door", "kind": kind, "strict": lv == {"Door"}}
        elif lv in ({"Cupboard_open_or_close"}, {"Drawer_open_or_close"}):
            cls = next(iter(lv))
            if not pp(f, cls):
                continue
            if CAB_EXCL.search(t):
                reasons["cabinet"]["excluded word"] += 1
                continue
            out[f] = {**rec, "class": "cabinet", "kind": "cupboard" if cls.startswith("Cupboard") else "drawer"}
    os.makedirs(OUT, exist_ok=True)
    json.dump(out, open(f"{OUT}/new_selection.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    for cls in ("footsteps", "door", "cabinet"):
        ks = [k for k, v in out.items() if v["class"] == cls]
        kinds = Counter(out[k]["kind"] for k in ks)
        ups = len({out[k]["uploader"] for k in ks})
        extra = f", strict {sum(out[k].get('strict', False) for k in ks)}" if cls == "door" else ""
        print(f"{cls:10s} kept {len(ks):4d} clips / {ups:3d} uploaders{extra}; kinds {dict(kinds)}; "
              f"dropped {dict(reasons[cls])}")


def check():
    import step0_fingerprint as F
    import glob
    sel = json.load(open(f"{OUT}/new_selection.json", encoding="utf-8"))
    thr = json.load(open("results/step0/fingerprint_groups.json", encoding="utf-8"))["threshold_aligned_matches"]
    old = json.load(open("results/step0/fp_selection.json", encoding="utf-8"))
    new_ids = sorted((k for k in sel if os.path.exists(f"{CLIPS}/{k}.wav")), key=int)
    missing = sorted(set(sel) - set(new_ids), key=int)
    old_ids = sorted((k for k in old if os.path.exists(f"{CLIPS}/{k}.wav") and k not in sel), key=int)
    ids = new_ids + old_ids
    fps = [F.fingerprint(F.load(f"{CLIPS}/{k}.wav")) for k in ids]
    index = F.Index(fps)
    cls_of = {k: sel[k]["class"] for k in new_ids} | {k: old[k]["pool"] for k in old_ids}
    links, null_best = [], []
    for a, k in enumerate(new_ids):
        h, t = fps[a]
        best_unrel = 0
        for j, c in index.best(h, t, exclude=a).items():
            other = ids[j]
            if c >= thr:
                links.append({"clip": k, "other": other, "other_class": cls_of[other], "count": int(c)})
            if cls_of[other] not in (sel[k]["class"], "door", "cabinet") and not (
                    sel[k]["class"] in ("door", "cabinet") and cls_of[other] in ("door", "cabinet", "knock")):
                best_unrel = max(best_unrel, int(c))
        null_best.append(best_unrel)
    sub = {k: {"class": sel[k]["class"]} for k in new_ids}
    musan = sorted(glob.glob(os.path.join(MUSAN, "*", "*.wav")))
    nindex = F.Index(fps[:len(new_ids)])
    musan_matches = []
    for p in musan:
        h, t = F.fingerprint(F.load(p))
        for j, c in nindex.best(h, t).items():
            if c >= thr:
                musan_matches.append({"musan": os.path.relpath(p, MUSAN).replace("\\", "/"), "clip": new_ids[j],
                                      "count": int(c)})
    nb = sorted(null_best)
    res = {"threshold": thr, "n_new": len(new_ids), "missing_audio": missing, "n_old_indexed": len(old_ids),
           "links": links, "musan_matches": musan_matches,
           "musan_excluded": sorted({m["clip"] for m in musan_matches}, key=int),
           "null_false_match_rate": sum(b >= thr for b in nb) / max(1, len(nb)),
           "null_quantiles": {q: nb[min(len(nb) - 1, int(q * len(nb)))] for q in (0.5, 0.9, 0.99)} if nb else {},
           "classes": dict(Counter(sub[k]["class"] for k in sub))}
    json.dump(res, open(f"{OUT}/new_check.json", "w", encoding="utf-8"), indent=1)
    print(f"new clips with audio {len(new_ids)} (missing {len(missing)}), old indexed {len(old_ids)}, threshold {thr}")
    print(f"links >= threshold: {len(links)}; MUSAN matches {len(musan_matches)} -> excluded {res['musan_excluded']}")
    print(f"null (unrelated classes): false-match rate {res['null_false_match_rate']:.4f}, quantiles "
          f"{res['null_quantiles']}")
    for l in links:
        print("  link", l)


def allocate():
    sel = json.load(open(f"{OUT}/new_selection.json", encoding="utf-8"))
    chk = json.load(open(f"{OUT}/new_check.json", encoding="utf-8"))
    fin = json.load(open("results/step0/split_final.json", encoding="utf-8"))
    oldsel = json.load(open("results/step0/fsd50k_selection.json", encoding="utf-8"))
    pools = json.load(open("results/step0/event_decoy_pools.json", encoding="utf-8"))["clips"]
    fsnew = json.load(open("results/step0/freesound_new_subset.json", encoding="utf-8"))["kept"]
    up_split = defaultdict(set)
    for k, m in fin["manifest"].items():                  # "excluded" (e.g. MUSAN matches) is not a split
        up = (pools.get(k) or oldsel.get(k) or {}).get("uploader")
        if up and m["split"] != "excluded":
            up_split[up].add(m["split"])
    fs_clash = sorted((k for k, v in fsnew.items() if up_split.get(v["uploader"]) and
                       up_split[v["uploader"]] != {v["split"]}), key=int)
    for k, v in fsnew.items():                            # FSD50K mapping wins; clashing Freesound clips leave v0.4
        if k not in fs_clash:
            up_split[v["uploader"]].add(v["split"])
    clash = {u: s for u, s in up_split.items() if len(s) > 1}
    excluded = set(chk["musan_excluded"]) | set(chk["missing_audio"])
    ids = sorted((k for k in sel if k not in excluded), key=int)
    parent = {k: k for k in ids}

    def root(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = root(a), root(b)
        if ra != rb:
            parent[max(ra, rb, key=int)] = min(ra, rb, key=int)

    by_up = defaultdict(list)
    for k in ids:
        by_up[sel[k]["uploader"]].append(k)
    for ks in by_up.values():
        for k in ks[1:]:
            union(ks[0], k)
    forced = {}
    for l in chk["links"]:
        a, b = l["clip"], l["other"]
        if a in parent and b in parent:
            union(a, b)
        elif a in parent and b in fin["manifest"]:
            forced[a] = fin["manifest"][b]["split"]
    groups = defaultdict(list)
    for k in ids:
        groups[root(k)].append(k)
    split_of, how = {}, {}
    for g, ks in groups.items():
        known = set()
        for k in ks:
            known |= up_split.get(sel[k]["uploader"], set())
            if k in forced:
                known.add(forced[k])
        if len(known) == 1:
            split_of[g], how[g] = known.pop(), "inherited"
        elif len(known) > 1:
            split_of[g], how[g] = "excluded", f"conflict {sorted(known)}"
    rng = random.Random(SEED)
    for cls in ("footsteps", "door", "cabinet"):
        free = sorted((g for g in groups if g not in split_of and sel[groups[g][0]]["class"] == cls), key=int)
        rng.shuffle(free)
        n = len(free)
        cut = [round(n * 0.30), round(n * 0.45), round(n * 0.55)]
        for i, g in enumerate(free):
            split_of[g] = "test" if i < cut[0] else "replication" if i < cut[1] else "dev" if i < cut[2] else "train"
            how[g] = "proportional"
    manifest = {k: {"class": sel[k]["class"], "kind": sel[k]["kind"], "group": f"n{root(k)}",
                    "split": split_of[root(k)], "how": how[root(k)], "uploader": sel[k]["uploader"]} for k in ids}
    table = {}
    for cls in ("footsteps", "door", "cabinet"):
        table[cls] = {}
        for sp in ("train", "dev", "test", "replication", "excluded"):
            ks = [k for k, m in manifest.items() if m["class"] == cls and m["split"] == sp]
            table[cls][sp] = {"clips": len(ks), "uploaders": len({manifest[k]["uploader"] for k in ks}),
                              "groups": len({manifest[k]["group"] for k in ks}),
                              "kinds": dict(Counter(manifest[k]["kind"] for k in ks))}
    res = {"seed": SEED, "uploader_split_clashes_v03": {u: sorted(s) for u, s in clash.items()},
           "freesound_new_excluded_in_v04": {k: {"uploader": fsnew[k]["uploader"], "split_v03": fsnew[k]["split"],
                                                  "fsd50k_splits": sorted(up_split[fsnew[k]["uploader"]])}
                                             for k in fs_clash},
           "excluded_clips": sorted(excluded, key=int), "table": table, "manifest": manifest}
    json.dump(res, open(f"{OUT}/new_split.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print(f"v0.3 uploaders still in more than one split: {len(clash)}; Freesound-new clips leaving v0.4 (uploader "
          f"also in another FSD50K split): {fs_clash}; excluded new clips {len(excluded)}")
    for cls, t in table.items():
        print(cls, {sp: (v["clips"], v["uploaders"], v["groups"]) for sp, v in t.items()})
        print("   kinds", {sp: v["kinds"] for sp, v in t.items() if v["clips"]})
    short = {cls: t["test"]["groups"] for cls, t in table.items() if t["test"]["groups"] < 8}
    print("test minimum (8 groups) not met:" if short else "test minimum (8 groups) met for all classes", short or "")


if __name__ == "__main__":
    {"select": select, "check": check, "allocate": allocate}[sys.argv[1]]()
